 "content": "def transform(grid):
    """Copy the marked interior of a framed rectangle to equally sized frames."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    boxes = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = all(grid[r0][c] == color and grid[r1][c] == color
                        for c in range(c0, c1 + 1)) and all(
            grid[r][c0] == color and grid[r][c1] == color
            for r in range(r0, r1 + 1))
        if perimeter:
            boxes.append((color, r0, r1, c0, c1))

    sources = []
    for color, r0, r1, c0, c1 in boxes:
        marked = any(grid[r][c] == color
                     for r in range(r0 + 1, r1) for c in range(c0 + 1, c1))
        if marked:
            sources.append((color, r0, r1, c0, c1))
    if not sources:
        return [row[:] for row in grid]
    # The patterned frame is the source; record its interior mask.
    color, r0, r1, c0, c1 = sources[0]
    pattern = [[grid[r][c] == color for c in range(c0 + 1, c1)]
               for r in range(r0 + 1, r1)]
    size = (r1 - r0, c1 - c0)

    out = [row[:] for row in grid]
    for target_color, a, b, x, y in boxes:
        if target_color == color and (a, b, x, y) == (r0, r1, c0, c1):
            continue
        if (b - a, y - x) == size:
            for i, r in enumerate(range(a + 1, b)):
                for j, c in enumerate(range(x + 1, y)):
                    out[r][c] = target_color if pattern[i][j] else 0
        else:
            # Frames of a different size are distractors and are removed.
            for r in range(a, b + 1):
                for c in range(x, y + 1):
                    if out[r][c] == target_color:
                        out[r][c] = 0
    return out
